@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700;800&display=swap');
:root{--ink:#101319;--panel:#191d24;--panel2:#20252d;--paper:#f0ede5;--muted:#9ca0a4;--orange:#f05a37;--gold:#e5b35d;--line:rgba(255,255,255,.1);font-family:Inter,Arial,sans-serif;color:var(--paper);background:var(--ink);font-synthesis:none}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#101319}body{min-height:100svh;background:radial-gradient(ellipse at 68% 12%,#25252a 0,#15181e 38%,#101319 75%);overflow-x:hidden}.app-shell{width:min(1360px,100%);min-height:100svh;margin:auto;padding:0 6.1%;position:relative}.topbar{height:72px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:2}.brand{display:flex;align-items:center;gap:11px;color:#f5f2ea;text-decoration:none;font:800 15px 'Barlow Condensed',sans-serif;letter-spacing:1.55px}.brand-mark{width:30px;height:30px;display:grid;place-items:center;background:var(--orange);color:white;font-size:21px;line-height:1}.brand-light{color:#97999a;margin-left:4px}.top-note,.sound-toggle,.eyebrow,.menu-meta,.selection-hint,.selected-info small,.selected-village,.menu-footer,.hud-sub,.round-clock span,.round-clock small,.control-tip,.result-kicker{font:500 10px 'DM Mono',monospace;letter-spacing:1.25px}.top-note{color:#afb1b0;display:flex;align-items:center;gap:9px}.live-dot{width:6px;height:6px;border-radius:50%;background:#e8b360;box-shadow:0 0 8px #e8b360}.sound-toggle{border:1px solid var(--line);background:#ffffff05;color:#dedbd4;padding:9px 12px;cursor:pointer;letter-spacing:.7px}.sound-toggle span{font-size:9px;color:#b5b4b1}.screen{position:relative}.menu-screen{min-height:calc(100svh - 72px);padding-top:45px;padding-bottom:18px}.menu-copy{position:relative;z-index:1;width:55%;min-height:280px}.eyebrow{color:#b4b4af;letter-spacing:1.6px}.menu-copy .eyebrow{margin:0 0 13px}.menu-copy .eyebrow span{color:var(--orange)}h1{font:900 clamp(54px,7vw,91px)/.82 'Barlow Condensed',Impact,sans-serif;letter-spacing:-1.6px;margin:0;color:#f2e