)}.hero-silhouette span{position:absolute;left:23px;top:146px;width:178px;height:136px;background:#f05a37;clip-path:polygon(27% 0,67% 4%,100% 100%,0 100%);z-index:0}.hero-caption{position:absolute;right:1%;bottom:16px;display:flex;flex-direction:column;text-align:right;color:#e3b15f}.hero-caption span{font-size:18px}.hero-caption small{font:9px 'DM Mono',monospace;letter-spacing:2px;color:#b4aba0}.selection-panel{position:relative;z-index:1;margin-top:8px}.selection-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.selection-heading .eyebrow{font-size:9px;color:#d09d57;margin:0 0 5px}.selection-heading h2{font:800 23px/1 'Barlow Condensed',sans-serif;letter-spacing:.7px;margin:0}.selection-heading h2 span{color:var(--orange)}.selection-hint{color:#888d90;font-size:9px}.selection-hint b{color:#efb65c;font-size:13px;margin-left:4px}.character-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.character-card{position:relative;overflow:hidden;text-align:left;height:151px;padding:0;border:1px solid #ffffff18;background:linear-gradient(145deg,#272b31,#1b1f26);color:var(--paper);cursor:pointer;transition:transform .18s,border-color .18s,background .18s}.character-card:hover{transform:translateY(-3px);border-color:#e3b15f88}.character-card.selected{border:1px solid var(--orange);background:linear-gradient(150deg,#343035,#202329);box-shadow:inset 0 -3px var(--orange)}.card-index{position:absolute;z-index:2;top:9px;left:10px;font:10px 'DM Mono',monospace;color:#9da0a0}.card-rank{position:absolute;z-index:2;right:10px;top:9px;color:#d2a35d;font:9px 'DM Mono',monospace}.card-art{position:absolute;right:3px;top:0;width:58%;height:100%;opacity:.94;transition:transform .3s}.character-card:hover .card-art{transform:scale(1.05) translateX(-3px)}.card-art:before{content:'';position:absolute;width:72px;height:72px;right:11px;top:12px;border-radius:50%;background:var(--glow);opacity:.85}.card-art:after{content:'';position:absolute;right:8px;bottom:-9px;width:85px;height:105px;background:var(--coat);clip-path:polygon(26% 0,74% 0,100% 100%,0 100%)}.card-head{position:absolute;z-index:1;width:47px;height:53px;right:28px;top:27px;background:var(--skin);clip-path:polygon(17% 5%,80% 0,100% 61%,66% 100%,18% 82%,0 28%)}.card-hair{position:absolute;z-index:2;right:21px;top:19px;width:61px;height:35px;background:var(--hair);clip-path:polygon(0 41%,8% 0,28% 22%,42% 0,59% 21%,81% 0,100% 35%,79% 71%,72% 45%,44% 69%,16% 53%)}.card-band{position:absolute;z-index:3;right:27px;top:39px;width:46px;height:7px;background:#d9d2be;transform:rotate(-6deg);opacity:.9}.card-band:after{content:'✦';position:absolute;left:20px;top:-3px;color:#30353a;font-size:9px}.card-eye{position:absolute;z-index:4;right:38px;top:49px;width:16px;height:3px;background:#17191e;transform:rotate(-4deg)}.card-name{position:absolute;z-index:4;bottom:30px;left:12px;font:800 19px/1 'Barlow Condensed',sans-serif;letter-spacing:.3px}.card-role{position:absolute;z-index:4;bottom:12px;left:12px;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#a5a5a2}.selected-info{display:flex;align-items:center;gap:10px}.selected-marker{color:var(--orange);font-size:19px}.selected-info div{display:flex;flex-direction:column;gap:3px}.selected-info small{color:#8f9295;font-size:8px}.selected-info strong{font:700 14px 'Barlow Condensed',sans-serif;letter-spacing:.5px}.selected-village{margin-left:12px;border-left:1px solid #ffffff25;padding-left:12px;color:#a9aaa5;font-size:8px}.selection-footer{display:flex;justify-content:space-between;align-items:center;margin-top:14px}.fight-button{height:42px;width:204px;border:0;background:var(--orange);color:white;font:700 11px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer;clip-path:polygon(0 0,92% 0,100% 25%,100% 100%,8% 100%,0 75%);transition:background .2s,transform .2s}.fight-button:hover{background:#ff704b;transform:translateY(-2px)}.fight-button span{font-size:17px;margin-left:13px}.menu-footer{display:flex;justify-content:space-between;color:#666b6e;font-size:8px;padding:19px 0 4px;border-top:1px solid #ffffff12;margin-top:19px}.hidden{display:none!important}
/* Arena */
.fight-screen{padding:25px 0 18px}.arena-top{height:72px;display:grid;grid-template-columns:1fr 94px 1fr;gap:22px;align-items:start;position:relative;padding:0 35px}.fighter-hud{padding-top:3px}.hud-name{display:flex;align-items:center;gap:9px;margin-bottom:8px}.enemy-hud .hud-name{justify-content:flex-end}.hud-name strong{font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:1px}.hud-tag{font:9px 'DM Mono',monospace;color:#fff;background:var(--orange);padding:4px 6px}.cpu-tag{background:#434850}.health-track{height:14px;background:#292d34;border:1px solid #474a4d;transform:skewX(-11deg);overflow:hidden}.health-fill{height:100%;width:100%;transition:width .25s;background:linear-gradient(90deg,#f05a37,#f29a4c);box-shadow:0 0 12px #f05a3770}.enemy-health{margin-left:auto;background:linear-gradient(90deg,#e1ac55,#f16a43)}.hud-sub{display:flex;justify-content:space-between;margin-top:6px;font-size:8px;color:#8f9497}.hud-sub span{color:#e4b45f;letter-spacing:4px}.enemy-hud .hud-sub{flex-direction:row-reverse}.round-clock{text-align:center;display:flex;flex-direction:column;align-items:center;margin-top:-3px}.round-clock span{color:#b2b1ab;font-size:8px}.round-clock span b{color:#f3b85d}.round-clock strong{font:800 31px/.95 'Barlow Condensed',sans-serif;color:#f3eee5}.round-clock small{font-size:7px;color:#828589;margin-top:3px}.exit-button{position:absolute;right:-25px;top:0;border:1px solid var(--line);background:#ffffff08;color:#b9b9b4;width:27px;height:27px;cursor:pointer}.arena-wrap{position:relative;width:100%;aspect-ratio:16/8.1;max-height:calc(100svh - 252px);min-height:300px;overflow:hidden;border:1px solid #e3b15f44;background:#14191c;box-shadow:0 16px 70px #0008}.arena-wrap canvas{display:block;width:100%;height:100%;touch-action:none}.fight-announcer{position:absolute;left:50%;top:23%;transform:translate(-50%,-50%);font:900 clamp(34px,6vw,67px)/1 'Barlow Condensed',sans-serif;letter-spacing:4px;color:#fff1d2;text-shadow:0 4px 1px #772d27,0 0 25px #e99e5288;pointer-events:none;opacity:0;transition:opacity .2s}.fight-announcer.show{opacity:1}.match-result{position:absolute;inset:0;background:#111319d9;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;backdrop-filter:blur(4px)}.result-kicker{color:#e3b15f;font-size:9px}.match-result strong{font:900 clamp(48px,8vw,82px)/1 'Barlow Condensed',sans-serif;color:#f5eee2;margin:5px}.match-result p{font-size:12px;color:#b8b8b2;margin:2px 0 16px}.match-result button{border:0;background:var(--orange);padding:12px 23px;color:white;font:700 10px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}.match-result button span{font-size:16px;margin-left:8px}.match-result .result-menu{margin-top:8px;background:transparent;color:#aaa;border:1px solid #ffffff30;padding:9px 17px}.controls-bar{display:flex;align-items:center;justify-content:space-between;height:50px;color:#929594}.control-tip{display:flex;align-items:center;gap:5px;font-size:8px}.control-tip kbd{font:10px 'DM Mono',monospace;border:1px solid #ffffff25;background:#ffffff08;padding:5px 7px;color:#e5e3dd;margin-left:5px}.mobile-tip{display:none}.touch-controls{display:none}
