action-pad{display:flex;align-items:center;gap:8px}.touch-controls button{touch-action:none;border:1px solid #ffffff25;background:#252a31;color:#eee8dc;width:51px;height:48px;clip-path:polygon(8% 0,100% 0,100% 85%,91% 100%,0 100%,0 12%);font:700 12px 'DM Mono',monospace}.touch-controls button:active,.touch-controls button.pressed{background:#f05a37}.touch-controls .jump-control{}.touch-controls .guard-touch{font-size:8px;color:#d4be91}.touch-controls .special-touch{background:#a84235;color:#fff1d2;font-size:23px}.touch-controls .attack-touch{background:#e65a39;color:white}.fight-screen{min-height:calc(100svh - 58px)}.arena-wrap{flex:1}.fight-screen:not(.hidden){display:flex;flex-direction:column}.arena-wrap{width:100%}.menu-footer span:nth-child(2){display:none}}
@media(max-width:430px){.top-note{letter-spacing:.4px;font-size:7px}.brand{font-size:13px}.brand-mark{width:26px;height:26px}.sound-toggle span{display:none}.menu-screen{padding-top:22px}.menu-copy{min-height:216px;width:75%}.menu-copy .eyebrow{font-size:8px}h1{font-size:56px}.intro{font-size:10px;max-width:245px}.menu-meta{font-size:7px}.hero-art{width:54%;height:220px;right:-5%;top:7px}.sun-disc{width:155px;height:155px;right:17%;top:16px}.hero-ring{width:200px;height:200px;right:4%}.ring-two{width:180px;height:180px}.hero-kanji{font-size:110px;right:17%;top:38px}.hero-silhouette{transform:scale(.65);right:6%}.hero-caption{right:0;bottom:6px}.hero-caption span{font-size:14px}.hero-caption small{font-size:7px}.selection-heading{align-items:center}.selection-heading h2{font-size:17px}.selection-heading .eyebrow{font-size:8px}.selection-hint{font-size:6px;letter-spacing:.5px}.character-grid{gap:5px}.character-card{height:112px}.card-name{font-size:14px;left:6px;bottom:25px}.card-role{font-size:6px;letter-spacing:.3px;left:6px;bottom:9px}.card-art:before{width:48px;height:48px;right:4px;top:25px}.card-art:after{width:58px}.card-head{right:11px;top:38px;transform:scale(.72)}.card-hair{right:6px;top:30px;transform:scale(.72)}.card-band{right:13px;top:47px;transform:rotate(-6deg) scale(.72)}.card-eye{right:23px;top:52px}.selection-footer{margin-top:11px}.selected-info{gap:6px}.selected-marker{font-size:15px}.selected-info small{font-size:6px}.selected-info strong{font-size:12px}.selected-village{font-size:6px;margin-left:4px;padding-left:6px}.fight-button{width:151px;height:38px;font-size:9px}.fight-button span{margin-left:4px}.menu-footer{font-size:6px}.arena-top{padding:0 15px;grid-template-columns:1fr 50px 1fr;gap:6px}.hud-name{gap:5px}.hud-name strong{font-size:15px}.hud-sub{font-size:6px}.arena-wrap{aspect-ratio:1/1;max-height:43svh}.touch-controls button{width:44px;height:45px}.touch-controls{padding-top:8px}.move-pad,.action-pad{gap:5px}}
@media(orientation:landscape) and (max-height:520px){.fight-screen{padding-top:10px}.arena-top{height:53px}.arena-wrap{max-height:calc(100svh - 135px);min-height:0;aspect-ratio:16/7}.touch-controls{padding:5px 2px}.touch-controls button{height:39px;width:47px}.controls-bar{height:25px}.menu-screen{padding-top:16px}.menu-copy{min-height:205px}.hero-art{height:225px}.character-card{height:105px}.menu-footer{margin-top:9px;padding-top:9px}}

const roster=[
 {name:'NARUTO',full:'NARUTO UZUMAKI',village:'HIDDEN LEAF',role:'THE REBEL',rank:'S',coat:'#e66a32',skin:'#e0a879',hair:'#f0b832',glow:'#d84d37',accent:'#262d37',style:'brawler'},
 {name:'SASUKE',full:'SASUKE UCHIHA',village:'HIDDEN LEAF',role:'THE PRODIGY',rank:'S',coat:'#315b76',skin:'#edc4a0',hair:'#171d29',glow:'#426f8b',accent:'#d8e3e1',style:'swift'},
 {name:'SAKURA',full:'SAKURA HARUNO',village:'HIDDEN LEAF',role:'THE POWERHOUSE',rank:'A',coat:'#ba4f59',skin:'#f0c4aa',hair:'#e4838a',glow:'#c85760',accent:'#f2e9dc',style:'power'},
 {name:'KAKASHI',full:'KAKASHI HATAKE',village:'HIDDEN LEAF',role:'THE COPY NINJA',rank:'S',coat:'#586c74',skin:'#dab394',hair:'#bac7c7',glow:'#72939a',accent:'#d4d7cf',style:'trickster'},
 {name:'GAARA',full:'GAARA',village:'HIDDEN SAND',role:'THE DESERT HEIR',rank:'A',coat:'#9b463a',skin:'#d6a888',hair:'#b94d48',glow:'#b7503f',accent:'#bf9559',style:'ranged'}
];
const grid=document.querySelector('#characterGrid');let selected=0,enemyIndex=1;
roster.forEach((c,i)=>{const card=document.createElement('button');card.className='character-card'+(!i?' selected':'');card.setAttribute('role','option');card.setAttribute('aria-selected',String(!i));card.style.setProperty('--coat',c.coat);card.style.setProperty('--skin',c.skin);card.style.setProperty('--hair',c.hair);card.style.setProperty('--glow',c.glow);card.innerHTML=`<span class="card-index">0${i+1}</span><span class="card-rank">${c.rank} ✦</span><span class="card-art"><i class="card-head"></i><i class="card-hair"></i><i class="card-band"></i><i class="card-eye"></i></span><strong class="card-name">${c.name}</strong><small class="card-role">${c.role}</small>`;card.addEventListener('click',()=>selectCharacter(i));grid.append(card)});
function selectCharacter(i){selected=i;document.querySelectorAll('.character-card').forEach((el,j)=>{el.classList.toggle('selected',j===i);el.setAttribute('aria-selected',String(j===i))});document.querySelector('#selectedName').textContent=roster[i].full;document.querySelector('#selectedVillage').textContent=roster[i].village}
const menu=document.querySelector('#menuScreen'),fight=document.querySelector('#fightScreen'),canvas=document.querySelector('#gameCanvas'),ctx=canvas.getContext('2d');
let W=960,H=480,raf,lastFrame=0,game=null,soundOn=true,audioCtx=null;
function resizeCanvas(){const r=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));W=960;H=480;ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}
new ResizeObserver(resizeCanvas).observe(canvas);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function startGame(){enemyIndex=(selected+1+Math.floor(Math.random()*4))%5;game={p:createFighter(selected,1),e:createFighter(enemyIndex,-1),timer:60,round:1,scoreP:0,scoreE:0,state:'ready',stateTime:2.2,projectiles:[],particles:[],shake:0,lastSecond:Date.now(),ended:false};document.querySelector('#playerName').textContent=roster[selected].name;document.querySelector('#enemyName').textContent=roster[enemyIndex].name;menu.classList.add('hidden');fight.classList.remove('hidden');document.querySelector('#matchResult').classList.add('hidden');document.querySelector('#announcer').textContent='READY?';document.querySelector('#announcer').classList.add('show');resizeCanvas();updateHud();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
function createFighter(index,side){return {index,x:side===1?260:700,y:0,vx:0,vy:0,side,health:100,facing:side===1?1:-1,grounded:true,attack:0,special:0,hitstun:0,guard:false,anim:0,aiWait:.8,aiMove:0}}
document.querySelector('#fightButton').addEventListener('click',startGame);
document.querySelector('#backButton').addEventListener('click',goMenu);document.querySelector('#resultMenu').addEventListener('click',goMenu);document.querySelector('#rematchButton').addEventListener('click',startGame);
function goMenu(){cancelAnimationFrame(raf);fight.classList.add('hidden');menu.classList.remove('hidden');game=null}
const held={};let touchIds=new Map();
const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'jump',KeyW:'jump',KeyJ:'attack',KeyK:'special',KeyL:'guard',Space:'attack'};
window.addEventListener('keydown',e=>{const a=keyMap[e.code];if(a){e.preventDefault();if(!held[a])action(a,true);held[a]=true}});window.addEventListener('keyup',e=>{const a=keyMap[e.code];if(a){held[a]=false;action(a,false)}});
document.querySelectorAll('[data-action]').forEach(btn=>{const a=btn.dataset.action;btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);touchIds.set(e.pointerId,a);held[a]=true;btn.classList.add('pressed');action(a,true)});const release=e=>{if(touchIds.has(e.pointerId)){touchIds.delete(e.pointerId);held[a]=false;btn.classList.remove('pressed');action(a,false)}};btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release)});
function action(a,on){if(!game||game.state!=='fight'||!on)return;const p=game.p;if(a==='jump'&&p.grounded){p.vy=-440;p.grounded=false;playTone(360,.05)}if(a==='attack'&&p.attack<=0&&p.hitstun<=0){p.attack=.34;p.guard=false}if(a==='special'&&p.special<=0&&p.hitstun<=0){p.special=1.15;p.attack=.5;game.projectiles.push({x:p.x+p.facing*38,y:p.y-64,vx:p.facing*420,owner:'p',life:1.4,color:roster[p.index].glow});playTone(180,.13)}if(a==='guard')p.guard=on}
function playTone(freq,duration){if(!soundOn)return;try{audioCtx ||=new(window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch{}}
document.querySelector('#soundToggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.querySelector('span').textContent=soundOn?'SOUND ON':'SOUND OFF'});
function loop(now){if(!game)return;const dt=Math.min(.034,(now-lastFrame)/1000||.016);lastFrame=now;update(dt);draw();raf=requestAnimationFrame(loop)}
function update(dt){const g=game;if(g.state==='ready'){g.stateTime-=dt;if(g.stateTime<.25)document.querySelector('#announcer').textContent='FIGHT!';if(g.stateTime<=0){g.state='fight';document.querySelector('#announcer').classList.remove('show')}}else if(g.state==='fight'){g.timer-=dt;if(g.timer<=0){g.timer=0;finishRound(g.p.health>=g.e.health?'p':'e')}if(Date.now()-g.lastSecond>1000){g.lastSecond=Date.now();updateHud()}const p=g.p,e=g.e;updateFighter(p,dt,true);updateAI(e,p,dt);updateFighter(e,dt,false);if(p.attack>0&&p.attack<.23&&p.attack+dt>=.23)tryHit(p,e,18);if(e.attack>0&&e.attack<.23&&e.attack+dt>=.23)tryHit(e,p,roster[e.index].style==='power'?20:15);if(e.special>0&&e.special<.82&&e.special+dt>=.82){if(Math.abs(e.x-p.x)<145&&Math.abs(e.y-p.y)<35)tryHit(e,p,16)}updateProjectiles(dt);if(g.shake>0)g.shake=Math.max(0,g.shake-dt*20);if(p.health<=0||e.health<=0)finishRound(p.health>e.health?'p':'e')}
for(const q of g.particles){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=250*dt;q.life-=dt}g.particles=g.particles.filter(q=>q.life>0)}
function updateFighter(f,dt,isPlayer){f.anim+=dt;f.attack=Math.max(0,f.attack-dt);f.special=Math.max(0,f.special-dt);f.hitstun=Math.max(0,f.hitstun-dt);f.facing=(isPlayer?game.e.x:game.p.x)>f.x?1:-1;f.guard=isPlayer?!!held.guard:f.guard;if(f.hitstun<=0){if(isPlayer){const direction=(held.right?1:0)-(held.left?1:0);if(direction){f.vx=direction*205;f.guard=false}else f.vx*=.78;if(held.jump&&f.grounded){f.vy=-440;f.grounded=false}}else f.vx*=.78}f.x+=f.vx*dt;f.vy+=1050*dt;f.y+=f.vy*dt;if(f.y>=0){f.y=0;f.vy=0;f.grounded=true}f.x=clamp(f.x,65,895)}
function updateAI(e,p,dt){if(e.hitstun>0)return;e.aiWait-=dt;const dist=Math.abs(p.x-e.x);e.guard=false;if(e.aiWait<=0){if(dist>135){e.vx=(p.x>e.x?1:-1)*(115+Math.random()*40);e.aiMove=.3}else if(Math.random()<.22){e.guard=true;e.aiMove=.38}else if(Math.random()<.26&&dist>100){e.special=1.15;game.projectiles.push({x:e.x+e.facing*38,y:e.y-64,vx:e.facing*360,owner:'e',life:1.3,color:roster[e.index].glow});e.aiWait=1.6}else{e.attack=.34;e.aiWait=.85+Math.random()*.55}if(e.aiMove<=0)e.aiWait=.3+Math.random()*.4}e.aiMove-=dt;if(e.aiMove<=0)e.vx*=.7}
function tryHit(attacker,target,damage){if(attacker.hitstun>0)return;const distance=Math.abs(attacker.x-target.x);if(distance>112||Math.abs(attacker.y-target.y)>60)return;if(target.guard&&attacker.side!==target.side){target.health=Math.max(0,target.health-damage*.16);target.vx=attacker.facing*40;spawnSparks(target.x,target.y-55,'#c7c7c0',4);playTone(130,.04)}else{target.health=Math.max(0,target.health-damage);target.hitstun=.25;target.vx=attacker.facing*245;game.shake=5;spawnSparks(target.x,target.y-57,roster[attacker.index].glow,10);playTone(90,.09)}updateHud()}
function updateProjectiles(dt){game.projectiles=game.projectiles.filter(q=>{q.x+=q.vx*dt;q.life-=dt;const t=q.owner==='p'?game.e:game.p;if(Math.abs(q.x-t.x)<30&&Math.abs(q.y-(t.y-60))<48){if(t.guard){t.health=Math.max(0,t.health-5)}else{t.health=Math.max(0,t.health-13);t.hitstun=.2;t.vx=Math.sign(q.vx)*190}spawnSparks(q.x,q.y,q.color,12);playTone(110,.08);updateHud();return false}return q.life>0&&q.x>0&&q.x<W})}
function spawnSparks(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=50+Math.random()*180;game.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.2+Math.random()*.35,color,size:2+Math.random()*4})}}
function finishRound(winner){if(game.state!=='fight')return;game.state='roundover';if(winner==='p')game.scoreP++;else game.scoreE++;updateHud();const won=winner==='p';const result=document.querySelector('#matchResult');if(game.scoreP>=2||game.scoreE>=2){document.querySelector('#resultTitle').textContent=won?'VICTORY':'DEFEAT';document.querySelector('#resultText').textContent=won?'Your will burns brighter than ever.':'A true shinobi rises after every fall.';document.querySelector('#rematchButton').innerHTML='REMATCH <span>↻</span>';result.classList.remove('hidden')}else{document.querySelector('#announcer').textContent=won?'ROUND WON':'ROUND LOST';document.querySelector('#announcer').classList.add('show');setTimeout(()=>{if(!game)return;game.round++;game.p=createFighter(selected,1);game.e=createFighter(enemyIndex,-1);game.p.x=260;game.e.x=700;game.p.health=game.e.health=100;game.timer=60;game.state='ready';game.stateTime=2;game.lastSecond=Date.now();document.querySelector('#announcer').textContent='ROUND '+game.round;updateHud()},1700)}}
function updateHud(){if(!game)return;document.querySelector('#playerHealth').style.width=game.p.health+'%';document.querySelector('#enemyHealth').style.width=game.e.health+'%';document.querySelector('#timer').textContent=Math.ceil(game.timer).toString().padStart(2,'0');document.querySelector('#roundNumber').textContent=String(game.round).padStart(2,'0');document.querySelector('#playerWins').textContent='● '.repeat(game.scoreP)+'○ '.repeat(2-game.scoreP);document.querySelector('#enemyWins').textContent='● '.repeat(game.scoreE)+'○ '.repeat(2-game.scoreE)}

